package com.fooddelivery.order; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.*; @Entity @Table(name="orders") @Getter @Setter @NoArgsConstructor public class Order{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;String customerEmail;Long restaurantId;BigDecimal totalAmount;String deliveryAddress;String paymentMethod;String paymentId;String status;LocalDateTime orderTime;}